// And groups predicates with the AND operator between them.
func And(predicates ...predicate.IterationNote) predicate.IterationNote {
	return predicate.IterationNote(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.IterationNote) predicate.IterationNote {
	return predicate.IterationNote(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.IterationNote) predicate.IterationNote {
	return predicate.IterationNote(sql.NotPredicates(p))
}
